SELECT * FROM ( SELECT FROM demand_subscriptions s LEFT JOIN buildings sb ON sb.id = s.building_id WHERE s.active AND s.textbook_edition_id IS NULL
UNION ALL SELECT FROM demand_subscriptions s LEFT JOIN buildings sb ON sb.id = s.building_id WHERE s.active AND s.textbook_edition_id = #{textbookEditionId}
) candidates ORDER BY candidates.created_at, candidates.id

